        dpg.add_text('0', tag='node_count', color=[200, 200, 200])
        dpg.add_spacer(width=30)
        dpg.add_text('Connections:', color=[255, 150, 100])
        dpg.add_text('0', tag='connection_count', color=[200, 200, 200])

