                holdings_columns = [('Stock', 80), ('Original', 80), ('Shares', 80), ('Avg Cost', 100), ('Current Price', 120), ('Market Value', 120), ('Gain/Loss', 120), ('Weight %', 80), ('Actions', 100)]
                for label, width in holdings_columns:
                    dpg.add_table_column(label=label, width_fixed=True, init_width_or_weight=width)
