    def create_analyze_content(self):
        """Create portfolio analytics content"""
        with dpg.group(parent='portfolio_center_panel'):
            dpg.add_text('PORTFOLIO ANALYTICS', color=self.BLOOMBERG_ORANGE)
            dpg.add_separator()
