    """Create recent transactions efficiently"""
    recent_transactions = [('AAPL', 'BUY', '50 shares', '2024-01-20'), ('MSFT', 'BUY', '30 shares', '2024-01-18'), ('GOOGL', 'SELL', '10 shares', '2024-01-15')]
