def create_portfolio_status_bar(self):
    """Create portfolio status bar"""
    with dpg.group(horizontal=True):
        status_items = [('PORTFOLIO STATUS:', 'ACTIVE', self.BLOOMBERG_GREEN), ('REAL-TIME PRICING:', 'ENABLED', self.BLOOMBERG_GREEN), ('AUTO-REFRESH:', 'ON', self.BLOOMBERG_GREEN)]
        for i, (label, value, color) in enumerate(status_items):
            if i > 0:
                dpg.add_text(' | ', color=self.BLOOMBERG_GRAY)
