        field_mappings = [('symbol', 'Stock Symbol/Instrument', 'The column containing stock symbols', True), ('quantity', 'Quantity/Shares', 'The column containing number of shares', True), ('avg_price', 'Average Cost/Purchase Price', 'The column containing average purchase price', True), ('current_price', 'Current Price/LTP', 'Current market price (optional)', False), ('investment', 'Invested Amount', 'Total invested amount (optional)', False), ('current_value', 'Current Value', 'Current market value (optional)', False), ('pnl', 'P&L/Gain-Loss', 'Profit/Loss amount (optional)', False)]
        with dpg.table(header_row=True, borders_innerH=True, borders_outerH=True, height=250):
            dpg.add_table_column(label='Portfolio Field', width_fixed=True, init_width_or_weight=150)
