    def create_research_panel(self):
        """Create research and alerts panel"""
        with operation('create_research_panel'):
            with dpg.child_window(width=380, height=700, border=True):
                dpg.add_text('TRADE RESEARCH CENTER', color=self.BLOOMBERG_ORANGE)
                dpg.add_separator()
                dpg.add_text('RESEARCH TOOLS', color=self.BLOOMBERG_YELLOW)
                research_tools = ['Trade Flow Analysis', 'Tariff Impact Calculator', 'Route Optimization', 'Cost-Benefit Analysis', 'Risk Scenario Modeling', 'Compliance Checker']
                for tool in research_tools:
                    dpg.add_button(label=tool, width=-1, height=25)
                dpg.add_separator()
                dpg.add_text('TRADE ALERTS', color=self.BLOOMBERG_YELLOW)
                alerts = [('HIGH', 'Suez Canal: Congestion increasing', self.BLOOMBERG_RED), ('MED', 'US-China: New tech restrictions', self.BLOOMBERG_YELLOW), ('LOW', 'EU carbon border tax: Q2 implementation', self.BLOOMBERG_GREEN), ('HIGH', 'Red Sea: Security concerns affecting shipping', self.BLOOMBERG_RED), ('MED', 'WTO: New dispute resolution timeline', self.BLOOMBERG_YELLOW)]
                for level, alert, color in alerts:
                    with dpg.group(horizontal=True):
                        dpg.add_text(f'[{level}]', color=color)
