    dpg.add_separator()
    with dpg.group(horizontal=True):
        with dpg.group():
            dpg.add_text('Fincept Financial Terminal', color=self.BLOOMBERG_ORANGE)
            dpg.add_text('Professional Trading & Analytics Platform')
